workflow Main(source_availability_state, redaction_attestation_state, overnight_line_count_total, sanitized_log_evidence_payload) {
    alt (source_availability_state == "unavailable") {
        return "Logs were unavailable. No findings were produced."
    }

    alt (redaction_attestation_state != "verified") {
        halt "Redaction has not been verified. Stop analysis and request operator attention."
    }

    alt (overnight_line_count_total > 10000) {
        human_prompt "On-call approver: this batch exceeds 10,000 lines. Review the batch size and decide how the team should handle it. No analysis will be run." -> oversized_batch_review_response
        return "Batch exceeds 10,000 lines and was not analyzed. On-call review response: {oversized_batch_review_response}"
    } else {
        delegate "Group these verified-redacted overnight error log lines by likely cause and prepare a concise on-call report. Use only the supplied evidence:\n{sanitized_log_evidence_payload}" to ErrorAnalyst -> analyst_report_record expecting { report: string } retry 1 backoff 2s timeout 45s on_failure {
            halt "Report analysis or validation failed. Do not send; request human review."
        }

        human_prompt "On-call approver: review this prepared report, including any uncertain causes. No channel delivery is enabled.\n\n{analyst_report_record.report}\n\nEnter your review or assessment." -> on_call_review_response
        return "Report prepared for on-call review. No channel send was made.\nOn-call review: {on_call_review_response}\n{analyst_report_record.report}"
    }
}

workflow SetupGate {
    human_prompt "Workflow setup owner: provide structured answers for the team's timezone, configured log source, designated channel destination, and delivery approval expectations. Submitting these details does not activate scheduling or delivery; the operator must configure and validate the required tools separately." -> workflow_setup_confirmation_record
    return "Setup details received for operator configuration. Scheduling and channel delivery remain inactive. Submitted details: {workflow_setup_confirmation_record}"
}
